"""Git Pre-commit Hook Installer.

Installs a lightweight pre-commit hook into `.git/hooks/pre-commit` to prevent
committing code with CRITICAL or HIGH severity security flaws.
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Optional

from .git_tools import GitTools

HOOK_SCRIPT = """#!/usr/bin/env bash
# Pre-commit hook generated by Code Analysis Agent
#
# NOTE: the shell `-e` option is deliberately NOT enabled here. With `-e` the
# script would abort the moment the audit command returns non-zero, so the error
# message and the `exit 1` below would never run and the hook could never block.

echo "🔍 [code-agent] Running pre-commit security and quality checks..."

# Support both layouts: source checkout (PYTHONPATH=src) and pip install -e .
if [ -d "src/code_agent" ]; then
    PYTHONPATH=src python3 -m code_agent review --ref HEAD --fail-on high
else
    python3 -m code_agent review --ref HEAD --fail-on high
fi
EXIT_CODE=$?

if [ $EXIT_CODE -ne 0 ]; then
    echo "❌ [code-agent] Pre-commit check failed! Please resolve high-risk findings before committing."
    exit 1
fi

echo "✅ [code-agent] Pre-commit checks passed."
exit 0
"""


class PreCommitHook:
    """Manages installation and removal of repository git pre-commit hooks."""

    @staticmethod
    def _hooks_dir(repo_root: Optional[Path | str] = None) -> Path:
        """Resolves the `.git/hooks` directory for the given repository.

        When an explicit `repo_root` is supplied it is never replaced by the
        *process* cwd — doing so would silently install the hook into whichever
        repository the caller happens to run from. A subdirectory of a repo is
        still normalised to the repo root via git.
        """
        if repo_root is not None:
            root = GitTools.get_repo_root(repo_root) or Path(repo_root)
            return root.resolve() / ".git" / "hooks"
        root = GitTools.get_repo_root() or Path.cwd()
        return root / ".git" / "hooks"

    @classmethod
    def install(cls, repo_root: Optional[Path | str] = None) -> Path:
        hooks_dir = cls._hooks_dir(repo_root)
        if not hooks_dir.is_dir():
            raise RuntimeError(f"Directory '{hooks_dir}' does not exist. Is this a Git repository?")

        hook_file = hooks_dir / "pre-commit"
        hook_file.write_text(HOOK_SCRIPT, encoding="utf-8")
        # Ensure executable permissions
        try:
            hook_file.chmod(hook_file.stat().st_mode | 0o755)
        except Exception:
            pass
        return hook_file

    @classmethod
    def uninstall(cls, repo_root: Optional[Path | str] = None) -> bool:
        hook_file = cls._hooks_dir(repo_root) / "pre-commit"
        if hook_file.is_file():
            hook_file.unlink()
            return True
        return False
